async function exportFile(type){finishEditing();const name=(doc.title||'网络流程图').replace(/[<>:"/\\|?*]/g,'_');if(type==='json'){download(new Blob([JSON.stringify(root,null,2)],{type:'application/json'}),(root.title||name)+'.json');toast('已保存所有层级的流程 JSON');return;}const{xml,w,h}=renderer.exportSVG(),blob=new Blob([xml],{type:'image/svg+xml;charset=utf-8'});if(type==='svg'){download(blob,name+'.svg');return;}try{const scale=Math.min(2,12000/w,12000/h,Math.sqrt(32000000/(w*h))),canvas=document.createElement('canvas');canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale);const ctx=canvas.getContext('2d'),img=new Image(),url=URL.createObjectURL(blob);await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});ctx.scale(scale,scale);ctx.drawImage(img,0,0);URL.revokeObjectURL(url);const output=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!output)throw Error();download(output,name+'.png');}catch{toast('图片导出失败，请尝试 SVG。');}}
function exampleDocument(){const d=createDocument();d.title='通信与计算重叠示例';const add=(lane,shape,x,w,text)=>{const n=makeNode(shape,d.lanes[lane].id,x,text);n.width=w;d.nodes.push(n);return n;};const a=add(0,'rounded',170,180,'MatMul · 计算 A'),b=add(0,'rounded',370,210,'Attention · 计算 B'),c=add(0,'rounded',810,180,'MatMul · 计算 C'),r=add(1,'capsule',370,225,'AllReduce'),g=add(1,'parallelogram',610,180,'AllGather'),h=add(2,'rect',25,120,'H2D 拷贝'),o=add(2,'rect',610,150,'D2H 拷贝');addEdge(d,h.id,'right',a.id,'left');addEdge(d,a.id,'right',r.id,'left');addEdge(d,r.id,'right',c.id,'left');addEdge(d,b.id,'right',o.id,'left');addEdge(d,g.id,'right',c.id,'left');const child=ensureSubflow(b),n=makeNode('rect',child.lanes[0].id,30,'QK 计算'),cn=makeNode('capsule',child.lanes[1].id,220,'参数通信');child.nodes.push(n,cn);addEdge(child,n.id,'right',cn.id,'left');const deep=ensureSubflow(n);deep.nodes.push(makeNode('rect',deep.lanes[0].id,30,'GEMM'),makeNode('rect',deep.lanes[2].id,220,'暂存拷贝'));return d;}
window.flowApp=Object.freeze({getDocument:()=>clone(root),getCurrentDocument:()=>clone(doc),getSelection:()=>clone(items),getViewState:()=>({path:[...path],zoom,horizontalZoom:hzoom}),getScene:()=>renderer.getScene().nodes.map(n=>({id:n.node.id,scope:n.scope,...n.actual}))});
syncFlow();renderLibrary();render();hydrateIcons();try{const p=JSON.parse(localStorage.getItem(PREFS)||'{}');if(p.libraryWidth)$('.app-body').style.setProperty('--library-width',p.libraryWidth);if(p.inspectorWidth)$('.app-body').style.setProperty('--inspector-width',p.inspectorWidth);setPanel('library',!!p.library);setPanel('inspector',!!p.inspector);}catch{}if(location.hash.startsWith('#/flow/'))navigate(parseScope(location.hash.slice(7)),false);
